select exists (select 1 from pg_proc where pronamespace='public'::regnamespace and proname='increment_document_counter') and has_function_privilege('service_role','public.increment_document_counter(uuid,text)','EXECUTE') and not has_function_privilege('anon','public.increment_document_counter(uuid,text)','EXECUTE') and not has_function_privilege('authenticated','public.increment_document_counter(uuid,text)','EXECUTE') as ok;
